#!/usr/bin/env python3
"""Régénère les index localisés à partir du catalogue des guides."""
from pathlib import Path
from doc_catalog import GUIDES,LANGUAGES,LABELS,portal
ROOT=Path(__file__).resolve().parent.parent
TEXT={
'fr':('Documentation','Choisir un guide','Document','Source','HTML','PDF','Autres langues','Régénération','Chaque langue propose un démarrage rapide, un guide utilisateur et un guide développeur. Les guides utilisateur contiennent quatorze captures des vrais widgets en thème clair, dans leur langue.','Les 18 guides sont fournis en Markdown, HTML autonome et PDF. Les PDF anglais utilisent US Letter ; les autres utilisent A4.','Les captures utilisent un moteur de démonstration, des fichiers temporaires et des sessions privées. Aucun transfert ni presse-papiers du bureau n’est piloté.','L’export nécessite Python avec Markdown, Graphviz et WeasyPrint. Les captures nécessitent aussi les dépendances natives de Gad.','Tests et scénarios'),
'en-US':('Documentation','Choose a guide','Document','Source','HTML','PDF','Other languages','Regeneration','Each language has a Quick Start, User Guide, and Developer Guide. User guides include fourteen screenshots of real widgets in the light theme, in their own language.','All 18 guides are available as Markdown, standalone HTML, and PDF. English PDFs use US Letter; other editions use A4.','Captures use a demo engine, temporary files, and isolated sessions. They never control real desktop transfers or the clipboard.','Export requires Python with Markdown, Graphviz, and WeasyPrint. Captures also require Gad’s native build dependencies.','Tests and scenarios'),
'es-ES':('Documentación','Elegir una guía','Documento','Fuente','HTML','PDF','Otros idiomas','Regeneración','Cada idioma tiene una guía de inicio rápido, una guía de usuario y una guía de desarrollo. Las guías de usuario incluyen catorce capturas de los widgets reales con el tema claro y en su propio idioma.','Las 18 guías están disponibles en Markdown, HTML autónomo y PDF. Los PDF en inglés usan US Letter; las demás ediciones usan A4.','Las capturas utilizan un motor de demostración, archivos temporales y sesiones aisladas. No controlan las transferencias reales ni el portapapeles del escritorio.','La exportación requiere Python con Markdown, Graphviz y WeasyPrint. Las capturas también requieren las dependencias nativas de Gad.','Pruebas y escenarios'),
'pt-PT':('Documentação','Escolher um guia','Documento','Fonte','HTML','PDF','Outros idiomas','Regeneração','Cada idioma tem um guia de início rápido, um guia do utilizador e um guia de desenvolvimento. Os guias do utilizador incluem catorze capturas dos widgets reais com o tema claro e no respetivo idioma.','Os 18 guias estão disponíveis em Markdown, HTML autónomo e PDF. Os PDF em inglês usam US Letter; as outras edições usam A4.','As capturas utilizam um motor de demonstração, ficheiros temporários e sessões isoladas. Não controlam transferências reais nem a área de transferência do ambiente de trabalho.','A exportação requer Python com Markdown, Graphviz e WeasyPrint. As capturas também requerem as dependências nativas do Gad.','Testes e cenários'),
'de-DE':('Dokumentation','Ein Handbuch auswählen','Dokument','Quelle','HTML','PDF','Weitere Sprachen','Neu erzeugen','Für jede Sprache gibt es einen Schnellstart, ein Benutzerhandbuch und ein Entwicklerhandbuch. Die Benutzerhandbücher enthalten vierzehn Aufnahmen der echten Oberfläche im hellen Design und in ihrer jeweiligen Sprache.','Alle 18 Handbücher sind als Markdown, eigenständiges HTML und PDF verfügbar. Englische PDFs verwenden US Letter, alle anderen A4.','Die Aufnahmen verwenden eine Demo-Engine, temporäre Dateien und isolierte Sitzungen. Echte Übertragungen und die Zwischenablage des Desktops werden nicht gesteuert.','Für den Export werden Python mit Markdown, Graphviz und WeasyPrint benötigt. Die Aufnahmen benötigen zusätzlich die nativen Build-Abhängigkeiten von Gad.','Tests und Szenarien'),
'ja-JP':('ドキュメント','ガイドを選ぶ','ドキュメント','ソース','HTML','PDF','他の言語','再生成','各言語にクイックスタート、ユーザーガイド、開発者ガイドがあります。ユーザーガイドには、その言語の実際の画面をライトテーマで撮影した14枚の画像が含まれています。','18冊のガイドをMarkdown、単独で閲覧できるHTML、PDFで提供します。英語版PDFはUS Letter、その他はA4です。','撮影にはデモ用エンジン、一時ファイル、隔離されたセッションを使用します。実際の転送やデスクトップのクリップボードは操作しません。','書き出しにはMarkdown、Graphviz、WeasyPrintを利用できるPython環境が必要です。画面撮影にはGadのネイティブビルド依存関係も必要です。','テストとシナリオ')}


def main():
    for lang in LANGUAGES:
        t=TEXT[lang];lines=['# Gad — '+t[0],'','Version 0.1.0 · '+LABELS[lang]['language'],'','## '+t[1],'',t[8],'','| '+' | '.join(t[2:6])+' |','| --- | --- | --- | --- |']
        for guide in GUIDES:
            if guide.language==lang:lines.append('| '+guide.title+' | [Markdown]('+guide.source+') | [HTML](html/'+guide.slug+'.html) | [PDF](pdf/'+guide.slug+'.pdf) |')
        testing='TESTING.md' if lang=='fr' else 'TESTING.'+lang+'.md'
        lines+=['',t[9],'','['+t[12]+'](../'+testing+')','','## '+t[6],'']
        lines+=[' · '.join('['+LABELS[other]['language']+']('+portal(other)+')' for other in LANGUAGES if other!=lang),'','## '+t[7]+' {#regeneration}','',t[10],'',t[11],'','```sh','make docs-captures','make docs','make docs-check','```','','84 captures · 18 HTML · 18 PDF','']
        (ROOT/'docs'/portal(lang)).write_text('\n'.join(lines))


if __name__=='__main__':main()
